/* v34: one company, department reports, reviewable investment and endgame choices. */
const Expansion=E.extension;
const segmentName=id=>id==='retail'?'釣具店':id==='hq'?'本社・共通':id==='fishery'?'漁業':state.expansion.properties.find(p=>p.segmentId===id)?.name+' '+id.split('-').at(-1);
let expansionPreview=null,cruisePreview=null;
const expansionDisabled=()=>state.closed||state.ended||state.turn<25||state.turn>=120||!!state.actionLocked;
function expansionCommit(next){const start=state.entries.length;state=next;closeShop();renderPlanning();saveGame();if(state.entries.length>start)showNewEntries(state.entries.slice(start));}
function showDiversification(){Expansion.init(state);const f=state.expansion.fishery,props=state.expansion.properties,propertyOpen=Expansion.propertyUnlocked(state);
 openShop('多角化 · 不動産と漁業',`<p>漁業は第３期から、不動産は２期連続の税引後黒字決算を達成すると解禁します。会社の預金は共通、帳簿は全社で１つ。店舗は１店舗のまま、人員は店舗３人と漁業の船長１人・船員２人を別々に管理します。漁は船長１人でも出られますが漁獲は４割、船長＋船員１人で10割、船長＋船員２人で13割です。燃料・氷・餌も乗る人数に比例します。漁期は冬（12〜2月）で、春〜秋は赤字になりやすいので、船は秋に買うと資金繰りが楽です。</p>${propertyOpen?`<div class="career-heading"><img src="assets/characters/thirty.png" alt="サーティー"><h3>サーティー不動産</h3></div><p>サーティー「２期連続の黒字決算、おめでとう。返済後にお金が残るか、一緒に確かめましょう。」</p><div class="expansion-grid">${Expansion.market(state).map(p=>`<article><small>${['築浅','普通','築古'][p.ageBand]} · 築${p.age}年</small><h3>${p.name}</h3><b>${yen(p.price)}（本体・税抜）</b><p>満室家賃 ${yen(p.rent)}/月<br>表面利回り ${(p.yieldRate*100).toFixed(1)}％<br>償却 ${p.taxLife}年 · ${p.units}区画</p><button data-property-view="${p.id}">返済と収支を試算する</button></article>`).join('')}</div><p>候補は３か月ごとに更新。表示価格は土地・建物の合計で、建物の消費税と諸費用は別です。</p>`:''}<h3>漁業</h3>${f?.crew.some(x=>x.characterId==='madai')?`<div class="career-heading"><img src="assets/characters/madai.png" alt="マダイ"><p>船長・マダイ</p></div>${state.history.flatMap(h=>h.staffHints||[]).filter(h=>h.characterId==='madai').map(h=>`<p>クエの気づき：${h.text}</p>`).join('')}`:''}${f?`<p>船長 ${f.crew.filter(x=>x.role==='captain').length}/1人、船員 ${f.crew.filter(x=>x.role==='crew').length}/2人。${f.last?`直近の出漁 ${f.last.days}日、漁獲 ${f.last.quantity}kg、販売 ${f.last.sold}kg、自店供給 ${f.last.transfer||0}匹、鮮度ロス ${f.last.lost}kg。`:''}</p>${Expansion.coopHiring(state)?'<p class="audit-notice"><b>船を買った今月だけ、漁協の紹介で船長・船員を行動なしで採用できます。</b>来月からの欠員補充は、約５か月に１回の応募を待ちます。</p>':''}<button data-crew="captain" ${!Expansion.coopHiring(state)&&(expansionDisabled()||!E.recruitment(state).open)||state.closed||state.ended?'disabled':''}>マダイを船長に採用 · 月35万円</button><button data-crew="crew" ${!Expansion.coopHiring(state)&&(expansionDisabled()||!E.recruitment(state).open)||state.closed||state.ended?'disabled':''}>船員を採用 · 月28万円</button><p>マダイは漁の手際に個性があります。追加の人員募集は約５か月に１回の採用イベント時のみ（会社で最初の１人はいつでも）。いずれも給与に加え会社負担社保15％。採用は月１回、社長の行動を使います。採用月の操業能力は半分です。</p><label>出漁方針<select id="fishingPolicy">${[['normal','通常 · 最大20日'],['cautious','抑制 · 最大12日'],['rest','休漁']].map(([v,t])=>`<option value="${v}" ${f.policy===v?'selected':''}>${t}</option>`).join('')}</select></label><button id="saveFishingPolicy" ${state.closed||state.ended?'disabled':''}>方針を保存</button><h3>活きアジを自店へ供給</h3><p>月末に最大300匹を店の生け簀へ移し、翌月から販売。釣具店の在庫や空き容量で制限します。１匹80円の原価で振替し、社内売上や消費税は計上しません。燃料の配賦分と選別・輸送・飼育準備費を原価に含みます。</p><label>毎月の供給上限（匹）<input id="fishSupply" type="number" min="0" max="300" step="10" value="${f.supplyTarget||0}"></label><button id="saveFishSupply" ${state.closed||state.ended||!state.equipment.tank?'disabled':''}>供給設定を保存</button>${!state.equipment.tank?'<p>先に生け簀の設置が必要です。</p>':''}`:`<p>漁船・漁具 ${yen(E.gross(state,Expansion.RULES.boatCost))}。船長の採用まで売上はありません。船員２人まで増員可能。</p><button id="fisheryPlan">参入を試算する</button>`}<h3>保有する不動産</h3>${props.map(p=>`<p>${p.name} · 取得時築${p.age}年 / 現在築${p.age+Math.floor((state.turn-p.acquired)/12)}年<br>直近家賃 ${yen(p.last?.rent||0)} ／ 預り敷金 ${yen(p.deposit)} ／ 外部管理</p>`).join('')||'<p>まだ保有していません。</p>'}${props.length||f?'<button id="segmentMenuInside">事業別収支を見る</button>':''}`);
}
function investmentPlanView(kind,id){if(kind==='property'&&!Expansion.propertyUnlocked(state))throw Error('２期連続の黒字決算で不動産投資が解禁します。');const p=kind==='property'?Expansion.market(state).find(x=>x.id===id):Expansion.boatOffer();if(!p)throw Error('物件を選び直してください。');const a=currentBankAssessment(),q=Expansion.finance(state,p,a,kind),total=kind==='property'?Expansion.totalCost(state,p):E.gross(state,p.price);expansionPreview=null;
 openShop(p.name+' · 投資計画',`<p>会社預金 ${yen(cash())} ／ 格付け ${q.grade}</p><dl class="equipment-facts"><div><dt>取得時の総支払（税込）</dt><dd>${yen(total)}</dd></div><div><dt>融資上限 / 年利</dt><dd>${yen(q.limit)} / ${q.rate.toFixed(1)}％</dd></div><div><dt>返済期間</dt><dd>${q.months/12}年・翌月から元金均等</dd></div>${kind==='property'?`<div><dt>土地 / 建物（税抜）</dt><dd>${yen(p.land)} / ${yen(p.building)}</dd></div><div><dt>取得諸費用（税抜）</dt><dd>${yen(p.fees)}</dd></div><div><dt>期待年間NOI</dt><dd>${signedYen(p.noi)}</dd></div><div><dt>想定稼働率</dt><dd>${Math.round(p.occupancy*100)}％</dd></div>`:''}</dl>${bankerSpeech(kind==='property'?'古い物件は家賃に対して安くても、短い返済期間と修繕で資金繰りが苦しくなることがあります。NOIは家賃から運営費を引いた額。減価償却・借入返済・利息・法人税はまだ引いていません。':'船の購入代金は資産になり、毎月の減価償却が費用になります。元金返済は費用になりませんが、預金から出ていきます。船長や船員の給与は不漁でも残ります。')}<p>${kind==='property'?'融資枠は直近２期の経常利益＋償却から既存元金返済を引き、この物件の期待NOIの80％を加えた返済力で計算。格付け別の期間上限と担保掛目でも制限します。諸費用は自己資金です。住宅家賃・土地は消費税の対象外。建物・管理・修繕は10％。住宅賃貸用の建物税は取得原価に含め、管理・修繕の税は費用とします。仕入税額控除をしないゲーム簡略化です。':'設備枠は経常利益＋償却の最大10年分以内。漁獲は当月中に外販し、鮮度ロス５％を除いた売上を当月入金。漁獲売上の消費税はゲーム設定10％。生け簀を設置すると、活きアジを月末に自店へ原価供給できます。'}</p><label>借入希望額（円）<input id="expansionAmount" type="number" min="0" max="${q.limit}" step="10000" value="${q.limit}"></label><button data-expansion-preview="${kind}" data-asset-id="${p.id}">12か月試算して確認する</button><div id="expansionPlanResult"></div>`);
 el('expansionAmount').value=String(q.limit);
}
function previewExpansion(kind,id){const amount=Number(el('expansionAmount').value),p=kind==='property'?Expansion.market(state).find(x=>x.id===id):Expansion.boatOffer(),a=currentBankAssessment();if(!p)throw Error('掲載期限切れです。');const next=kind==='property'?Expansion.buyProperty(state,id,amount,a):Expansion.buyFishery(state,amount,a),r=Expansion.forecastExpansion(state,{kind,id,amount},a),down=Expansion.forecastExpansion(state,{kind,id,amount},a,12,true);expansionPreview={kind,id,amount,snapshot:JSON.stringify(state)};
 el('expansionPlanResult').innerHTML=`<h3>購入後の12か月予想</h3><p>取得直後の預金 <b>${yen(next.balances.預金)}</b> ／ 月末最低預金 <b>${yen(r.minimumCash||0)}</b></p><p>期間損益 ${signedYen(r.profit||0)} ／ ${r.error|| (r.ended?'途中で支払不能':'試算継続')}</p><p><b>悪化ケース</b>：不動産の稼働率▲20ポイント、漁獲▲25％、金利＋１ポイント。期間損益 ${signedYen(down.profit||0)}、最低月末預金 ${yen(down.minimumCash||0)}。${down.error||(down.ended?'途中で支払不能':'継続')}。</p><p>毎月補充案を使って店番。今月の投資は行動を消費。${kind==='fishery'?'翌月以降、最初の１人の例外または採用イベントのある月に船長・船員を順次採用する仮定です。採用待ちの休業・減員期間を含みます。実行後の採用は自動ではありません。':''}天候・修繕は同じ保存シードを使いますが、将来条件の保証ではありません。</p><div class="trend-scroll"><table class="trend-table"><thead><tr><th>月</th><th>税引後利益</th><th>会社預金</th><th>新事業・利息後利益</th></tr></thead><tbody>${r.rows.map(m=>`<tr><th>${turnName(m.turn)}</th><td>${signedYen(m.profit)}</td><td>${yen(m.cash)}</td><td>${signedYen(m.segments.rows.filter(x=>kind==='fishery'?x.id==='fishery':x.id===p.segmentId).reduce((n,x)=>n+x.profit,0))}</td></tr>`).join('')}</tbody></table></div><button id="confirmExpansion" ${r.error?'disabled':''}>この条件で取得を確定する</button><p>試算だけでは資金・ターン・乱数は変わりません。購入すると今月の社長の行動を使います。</p>`;
}
function confirmExpansion(){const p=expansionPreview;if(!p||p.snapshot!==JSON.stringify(state))throw Error('条件が変わりました。試算をやり直してください。');const a=currentBankAssessment(),n=p.kind==='property'?Expansion.buyProperty(state,p.id,p.amount,a):Expansion.buyFishery(state,p.amount,a);expansionPreview=null;expansionCommit(n);}
function segmentTable(start,end,expand=false){let rows=Expansion.segments(state,start,end).rows;if(!expand){const props=rows.filter(x=>x.id.startsWith('realestate:'));if(props.length){const merged={id:'property',sales:0,cost:0,gross:0,direct:0,contribution:0,interest:0,other:0,profit:0,allocation:0,afterAllocation:0,assets:0,debt:0};for(const r of props)for(const k of Object.keys(merged))if(k!=='id')merged[k]+=r[k]||0;rows=rows.filter(x=>!x.id.startsWith('realestate:'));rows.splice(1,0,merged);}}
 const fields=[['sales','外部売上'],['transferOut','社内供給（参考）'],['transferIn','社内受入（参考）'],['cost','原価・廃棄'],['gross','粗利'],['direct','直接費'],['contribution','部門利益'],['interest','支払利息'],['other','受取利息'],['profit','利息後利益'],['allocation','本社費配賦（参考）'],['afterAllocation','配賦後（参考）'],['assets','部門資産・期末'],['debt','部門借入・期末']];
 return `<div class="trend-scroll"><table class="trend-table"><thead><tr><th>科目</th>${rows.map(r=>`<th>${r.id==='property'?'投資不動産':segmentName(r.id)}</th>`).join('')}<th>全社合計</th></tr></thead><tbody>${fields.map(([key,label])=>`<tr><th>${label}</th>${rows.map(r=>`<td class="${r[key]<0?'negative':''}">${key==='afterAllocation'&&r.id==='hq'?'—':signedYen(r[key]||0)}</td>`).join('')}<td>${['allocation','afterAllocation','assets','transferOut','transferIn'].includes(key)?'—':signedYen(rows.reduce((n,r)=>n+(r[key]||0),0))}</td></tr>`).join('')}</tbody></table></div>`;
}
function segmentComparison(start,end){if(start<=12)return '<p>前年同期の実績はまだありません。</p>';const current=Expansion.segments(state,start,end),prior=Expansion.segments(state,start-12,end-12);return `<h3>前年同期との比較 · 利息後利益</h3><div class="trend-scroll"><table class="trend-table"><thead><tr><th>部門</th><th>今期</th><th>前年同期</th><th>増減</th><th>ROA（期末のみ）</th></tr></thead><tbody>${current.rows.map(r=>{const old=prior.rows.find(x=>x.id===r.id)?.profit||0,roa=end-start===11&&r.assets>0?r.contribution/r.assets:null;return `<tr><th>${segmentName(r.id)}</th><td>${signedYen(r.profit)}</td><td>${signedYen(old)}</td><td>${signedYen(r.profit-old)}</td><td>${roa===null?'—':(roa*100).toFixed(1)+'％'}</td></tr>`;}).join('')}</tbody></table></div><p>ROAは年間の部門利益÷その部門の期末資産。共通預金は含めません。途中の月を年換算して評価しません。</p>`;}
function showSegments(){const end=state.closed?state.turn:Math.max(1,state.turn-1),start=Math.floor((end-1)/12)*12+1;
 openShop('事業別収支',`<p>単位：円。全社B/Sは１つのまま、利益を事業別に分けます。社長の店番に追加給与はなく、役員報酬・社保は本社です。</p><h3>${turnName(end)} · 月次</h3>${segmentTable(end,end)}<h3>今期累計</h3>${segmentTable(start,end)}${segmentComparison(start,end)}<details><summary>不動産を物件ごとに展開</summary>${segmentTable(start,end,true)}</details><details><summary>直近３期の確定決算</summary>${state.history.filter(h=>h.turn%12===0).slice(-3).map(h=>`<h3>第${h.turn/12}期</h3>${segmentTable(h.turn-11,h.turn,true)}`).join('')||'<p>まだ決算実績はありません。</p>'}</details><p>各部門の利息後利益＋本社損益＝全社の経常利益。本社費の配賦は売上比による参考で、税額・銀行評価には使いません。共通預金は部門資産から除外。部門をやめても本社費が同じだけ減るわけではありません。</p>${state.expansion.properties.map(p=>`<p>${p.name}：直近NOI ${signedYen(p.last?.noi||0)}。NOIからその物件の元金・利息を引いた返済後CF ${signedYen((p.last?.noi||0)-state.entries.filter(e=>e.turn===end&&e.segmentId===p.segmentId&&(e.type?.startsWith('bankRepay.')||e.type==='bankInterest')).reduce((n,e)=>n+e.amount,0))}。</p>`).join('')}`);
}
function showMA(){Expansion.prepareMA(state);const m=state.expansion.ma;if(!m||['ineligible','failed','declined','sold'].includes(m.phase)){showFinalResult();return;}saveGame();
 openShop('10年目の商談 · 彼',`<div class="career-heading"><img src="assets/characters/kare.png" alt="チヌクエスト２の彼"><p>彼「この会社の株式、買い手に紹介させてもらおう。将来の稼ぐ力も、積み上げた純資産も見ているよ。」</p></div><p>直近３期のEBITDA：${m.values.map(yen).join(' ／ ')}<br>３期平均 <b>${yen(m.average)}</b> ／ 純資産 <b>${yen(m.net)}</b></p><p>株式100％の売却額＝純資産＋３期平均EBITDA×年数。利益の安定性・伸びを見て交渉します。希望条件の正式提出は２回まで。</p>${m.phase==='offer'?`<h3>最初の提示 ${yen(m.initial)}</h3><button data-ma="accept">飲む · 最終確認へ</button><button data-ma="reject">突っぱねる · 希望条件へ</button><button data-ma="discuss">応相談 · 内訳を確認</button>`:m.phase==='negotiate'?`<p>${m.response==='reject'?'クエ「その値段では手放せへんな。ワイの希望を聞いてや！」':'彼「純資産に何年分の稼ぐ力を上乗せするか、条件を教えてほしい。」'}</p><p>提出済み ${m.attempts.length} / 2回</p><label>希望する年数<input id="maMultiple" type="number" min="0.5" max="10" step="0.5" value="4"></label><button data-ma="offer">この希望条件を正式提出</button>`:`<h3>成約候補 ${yen(m.pending)}</h3><p>代金はクエ個人に入り、会社の売上や預金は変わりません。個人の譲渡税・仲介手数料はゲーム初版では扱いません。</p><button data-ma="confirm">株式売却を確定する</button>`}<button data-ma="decline">交渉を打ち切る</button><p>${m.attempts.map((x,i)=>`第${i+1}回：${x.multiple}年 / ${yen(x.price)} / ${x.accepted?'成約候補':'条件が折り合わず'}`).join('<br>')}</p>`);if(m.phase==='negotiate')el('maMultiple').value='4';
}
const finalBeforeExpansion=showFinalResult;
showFinalResult=function(){if(state.cashCrisis?.status==='pending'){showCashRescue();return;}Expansion.init(state);Expansion.prepareMA(state);const m=state.expansion.ma;if(m&&['offer','negotiate','confirm'].includes(m.phase)){showMA();return;}finalBeforeExpansion();const s=Expansion.score(state);if(!s)return;let best=0;try{best=Number(localStorage.getItem('que-v34-best')||0);if(s.total>best)localStorage.setItem('que-v34-best',String(s.total));}catch{}el('shopDialogBody').innerHTML=`<h2>10年間の評価 ${s.total} / 300点</h2><div class="review-grid"><article><small>収益性</small><b>${s.profitability} / 100</b></article><article><small>財務健全性</small><b>${s.health} / 100</b></article><article><small>個人資産</small><b>${s.wealth} / 100</b></article></div><p>端末内の自己ベスト ${Math.max(best,s.total)}点。途中終了は登録しません。</p><p>M&A前の個人資産点 ${s.wealthBefore} → ${s.wealth}。売却額 ${yen(s.sale)} ／ 個人資産 ${yen(s.personal)}。売却代金は１回だけ加算済みです。</p><details><summary>評価の計算方法</summary><p>収益性：最終３期平均の補正経常利益（受取利息と役員貸付の新規実行を控除）で計算。経常ROA10％で40点、経常利益率８％で30点、10期累計経常利益１億円で30点。財務健全性：役員貸付金・未収利息を控除し役員借入金を自己資本扱いにした自己資本比率50％で50点、債務償還年数０年で50点・15年以上で０点。役員借入による資金投入または緊急銀行融資のあった年は５点減。役員貸付残高に応じ10・25・40点減、未収利息があればさらに10点減。個人資産：個人預金＋役員借入金債権−役員貸付金−未収利息、１億円で100点。各項目の範囲は０〜満点。</p><p>銀行審査スコアとは別のゲーム評価です。公開ランキング・個人株式譲渡税はこの版では扱いません。</p></details>`+el('shopDialogBody').innerHTML;saveGame();};
function showCruise(){cruisePreview=null;openShop('巡航 · 期首からまとめて進める',`<p>今の仕入数量・支払方法（${choice.payment==='credit'?'買い掛け・翌月払い':'現金払い・2%割引'}）・価格・人員・出漁方針を固定し、社長は店番します。営業努力や季節に合わせた仕入調整は自動でしません。税務の特別な選択は引き継ぎません。</p><select id="cruiseMonths"><option value="12">12か月</option><option value="24">24か月</option><option value="36">36か月</option></select><button id="previewCruise" ${state.closed||state.ended||month(state.turn)!==4?'disabled':''}>決算と資金繰りを事前試算</button><div id="cruiseResult"></div><p>税務調査・スタッフの相談・物件案内・災害・修繕・短期借入の期日・資金余力不足で停止します。10期末を越えて進めません。</p>`);el('cruiseMonths').value='12';}
function previewCruise(){const months=Number(el('cruiseMonths').value),r=Expansion.cruise(state,choice.quantities,choice.price,months,choice.payment||'cash');cruisePreview={snapshot:JSON.stringify(state),choice:JSON.stringify(choice),result:r};el('cruiseResult').innerHTML=`<p>${r.rows.length}か月で停止予定：<b>${r.reason}</b>。終了時預金 ${yen(r.state.balances.預金)}</p><div class="trend-scroll"><table class="trend-table"><thead><tr><th>月</th><th>利益</th><th>月末預金</th></tr></thead><tbody>${r.rows.map(x=>`<tr><th>${turnName(x.turn)}</th><td>${signedYen(x.profit)}</td><td>${yen(x.cash)}</td></tr>`).join('')}</tbody></table></div><details><summary>巡航中の期末決算を見る</summary>${r.state.history.filter(h=>h.turn>=r.start&&h.turn%12===0).map(h=>formalBalance(h.balances,r.state.history.find(x=>x.turn===h.turn-12)?.balances||null,'前期末比')+formalPL(h.balances,null,'年次')).join('')||'<p>期末前に停止します。</p>'}</details><button id="confirmCruise" ${r.rows.length?'':'disabled'}>この条件で巡航を実行する</button>`;}
const taxNames={skim:'売上を少し抜く',privateGear:'私物の釣具を経費で買う',privateCar:'２台目の高級車',fiction:'架空の経費を立てる',inventory:'期末の在庫を少なく数える',privateBoat:'漁船を私的に使う',defer:'期末の売上を翌期に回す',living:'生活費の会社負担',idleBoat:'使っていない船の償却'};
function showTaxPolicy(){Expansion.init(state);const p=state.expansion.taxPolicy,locked=state.closed||state.ended||month(state.turn)!==4||p?.year===Math.ceil(state.turn/12);
 openShop('今期の経理と支出',`<p>あくまでゲームの演出です。実際とは異なります。支出・預金・利益・調査の結果を学ぶための選択です。</p><h3>通常の経営判断</h3><label>月額役員報酬（期首に１回）<input id="taxSalary" type="number" min="120000" max="1000000" step="10000" value="${state.officerSalary||300000}"></label><button id="saveTaxSalary" ${state.closed||state.ended||month(state.turn)!==4?'disabled':''}>報酬を設定する</button><button id="taxEquipment">設備投資</button><p>売れ残り処分は現物の在庫を減らし、商品廃棄損に計上します。</p><select id="taxStock">${E.PRODUCTS.map((p,i)=>`<option value="${i}">${p.name} · 在庫${state.inventory[i]}</option>`).join('')}</select><input id="taxStockQuantity" type="number" min="1" value="1" aria-label="処分数量"><button id="taxDispose" ${state.closed||state.ended?'disabled':''}>指定数量を処分する</button><h3>期首の方針 · 今期に１回</h3><label><input id="taxCareful" type="checkbox" ${p?.careful?'checked':''} ${locked?'disabled':''}>経理を丁寧にやる · 月２万円＋消費税</label><details><summary>特別な選択を開く</summary><p>現金や税額が一時的に動いても、調査で費用や控除が認められないことがあります。現金売上の５％を個人へ移す／私物は釣具30万円か車600万円・６年償却／実体のない支出50万円を個人へ移す／３月在庫20％を少なく計上して４月に戻す／船の私用で個人５万円・会社の燃料１万円増／３月売上50％を４月へ回す、というゲーム上の効果です。</p>${Object.entries(taxNames).filter(([k])=>!['living','idleBoat'].includes(k)).map(([k,v])=>`<label class="tax-command"><input type="checkbox" id="tax-${k}" ${locked?'disabled':''}>${v}</label>`).join('')}</details><button id="saveTaxPolicy" ${locked?'disabled':''}>今期の方針を確定する</button><p>未選択なら通常の自動記帳です。私物は道具か車のどちらか。生活費の付け回しは個人預金が生活費１か月未満の月に１回のみ。</p><button id="livingCharge" ${state.closed||state.ended||state.owner>=state.livingCost*1000||state.expansion.livingTurn===state.turn?'disabled':''}>今月の生活費10万円を会社負担にする</button>`);el('taxSalary').value=String(state.officerSalary||300000);el('taxStock').value='0';el('taxStockQuantity').value='1';}
const auditBeforeExpansion=showTaxAudit;
showTaxAudit=function(turn){const a=state.taxAudits?.find(x=>x.turn===turn)||state.taxAudits?.at(-1);if(!a?.rev2){auditBeforeExpansion(turn);return;}const targets=state.taxEvidence.filter(e=>e.auditTurn===a.turn);openShop('ムールの税務調査',`<p>あくまでゲームの演出です。実際とは異なります。</p><div class="career-heading"><img src="assets/characters/muuru.png" alt="調査官ムール"><p>ムール「帳簿と取引の内容を確認させてください。」</p></div><p>未回収の役員貸付利息 ${yen(a.unpaidInterest||0)}。回収の有無だけで追徴は決まりません。</p>${targets.map(e=>`<article class="staff-career"><h3>${taxNames[e.kind]||'経理資料の不足'} · ${turnName(e.turn)}</h3><p>所得への補正候補 ${yen(e.base)} ／ 消費税 ${yen(e.vat)}</p>${e.status==='auditPending'?`<p>回答：${e.response==='explain'?'説明する':e.response==='admit'?'認める':'未選択（翌月は認める扱い）'}</p><button data-finding="${e.id}" data-response="admit">認める</button><button data-finding="${e.id}" data-response="explain">説明する</button>`:`<p>${e.explained?'説明を確認':'補正済み'}</p>`}</article>`).join('')||'<p>今回は指摘なしでした。</p>'}<p>Q「過去の帳簿は書き換えず、翌月の帳簿で追加税額を計上するで。私的な支出は役員賞与扱いで個人にも課税。丁寧な経理は用途の説明に役立つけど、売上の抜きや架空支出、時期ずれを取り消すものではないで。」</p><p>加算税はゲーム上10％・重い指摘35％。個人への追加税は対象利益の20％で簡略計算。翌月の計上後、さらに翌月に会社が納付します。延滞税は省略。</p>${a.settledTurn?`<p>追加法人税 ${yen(a.corporateAdditional||0)} ／ 消費税 ${yen(a.vatAdditional||0)} ／ 加算税 ${yen(a.penalty||0)} ／ 個人税 ${yen(a.personalTax||0)}</p>`:''}`);a.notified=true;saveGame();};
