renderOverview=function(){Expansion.init(state);overviewBeforeExpansion();if(state.expansion.reviewHint)el('shopOverview').innerHTML+='<p>事業ごとの数字を見比べてみては。</p>';const t=Expansion.taxEstimate(state),months=state.livingCost?state.owner/(state.livingCost*1000):0;el('expansionGauges').innerHTML=`<div><small>今決算したら払う法人税等</small><b>${yen(t.amount)}</b></div><div class="${months<1?'negative':''}"><small>個人預金 ${yen(state.owner)}</small><b>生活費 あと${Math.max(0,months).toFixed(1)}か月</b></div>`;el('segmentTab').hidden=el('segmentMenu').hidden=!(state.expansion.properties.length||state.expansion.fishery);};
