const lessonBeforeExpansion=transactionAccountingLesson;
transactionAccountingLesson=function(entries,b){if(entries.some(e=>e.type==='propertyPurchase'||e.type==='fisheryPurchase'))return paymentLesson('新しい事業も同じ会社の帳簿や',['土地・建物・船に使った預金は資産に形を変える。土地は償却せず、建物や船は使う期間に分けて費用にするで。借入は売上にならへんし、元金返済も費用とは別や。']);if(entries.some(e=>e.type==='tenantDeposit'||e.type==='tenantRefund'))return paymentLesson('預かった敷金は会社の利益やないで',['入居者に返す義務があるから、預金の相手は「預り敷金」という負債や。家賃の売上とは分けて見るんやな。']);return lessonBeforeExpansion(entries,b);};
for(const [a,t] of Object.entries({土地:'償却しない固定資産。',賃貸建物:'貸し出す建物。取得時に定めた期間で償却。',船舶:'漁業の船と漁具。８年で償却。',車両:'車両。ゲームでは６年償却。',預り敷金:'入居者から預かった返還義務のあるお金。売上ではありません。',繰延売上:'ゲーム内の時期ずれ選択により、一時的に仮受扱いにした売上。翌期に戻し、調査の対象になります。'}))descriptions[a]=t;
