document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.id==='diversificationMenu')showDiversification();else if(b.dataset.propertyView)investmentPlanView('property',b.dataset.propertyView);else if(b.id==='fisheryPlan')investmentPlanView('fishery');else if(b.dataset.expansionPreview)previewExpansion(b.dataset.expansionPreview,b.dataset.assetId);else if(b.id==='confirmExpansion')confirmExpansion();else if(b.dataset.crew){expansionCommit(Expansion.hireCrew(state,b.dataset.crew));showDiversification();}else if(b.id==='saveFishSupply'){state=Expansion.setSupply(state,Number(el('fishSupply').value));saveGame();showDiversification();}else if(b.id==='saveFishingPolicy'){state=Expansion.setFishing(state,el('fishingPolicy').value);saveGame();showDiversification();}else if(['segmentTab','segmentMenu','segmentMenuInside','segmentMenuReport'].includes(b.id))showSegments();
 else if(b.dataset.ma){state=Expansion.negotiate(state,b.dataset.ma,b.dataset.ma==='offer'?Number(el('maMultiple').value):undefined);saveGame();showMA();}
 else if(b.id==='cruiseMenu')showCruise();else if(b.id==='previewCruise')previewCruise();else if(b.id==='confirmCruise'){if(!cruisePreview||cruisePreview.snapshot!==JSON.stringify(state)||cruisePreview.choice!==JSON.stringify(choice))throw Error('条件が変わりました。再試算してください。');const r=cruisePreview.result;cruisePreview=null;state=r.state;lastReport=r.report;statementReport=r.report;monthClosed=true;closeShop();saveGame();renderPlanning();openStatements();}
 else if(b.id==='taxPolicyMenu')showTaxPolicy();else if(b.id==='saveTaxPolicy')expansionCommit(Expansion.chooseTaxPolicy(state,Object.keys(taxNames).filter(k=>!['living','idleBoat'].includes(k)&&el('tax-'+k).checked),el('taxCareful').checked));else if(b.id==='saveTaxSalary'){state=Expansion.setSalary(state,Number(el('taxSalary').value));saveGame();renderPlanning();showTaxPolicy();}else if(b.id==='taxEquipment')showInvestments();else if(b.id==='taxDispose')expansionCommit(Expansion.disposeStock(state,Number(el('taxStock').value),Number(el('taxStockQuantity').value)));else if(b.id==='livingCharge')expansionCommit(Expansion.livingCharge(state));else if(b.dataset.finding){state=Expansion.resolveFinding(state,b.dataset.finding,b.dataset.response);saveGame();showTaxAudit();}
 }catch(err){toast(err.message);}});
