if(globalThis.crypto?.getRandomValues){if(!introComplete){const firstSeed=crypto.getRandomValues(new Uint32Array(1))[0]||73129;state.rng=firstSeed;Expansion.init(state);state.expansion.seed=firstSeed;}const newStateBeforeSeed=E.createState;E.createState=function(){const s=newStateBeforeSeed(),seed=crypto.getRandomValues(new Uint32Array(1))[0]||73129;s.rng=seed;s.expansion.seed=seed;return s;};}
