const reportWithDepartments=renderReport;
renderReport=function(){reportWithDepartments();const r=statementReport;if(!r||r.provisional||!r.entries?.length)return;const incoming=new Map(),outgoing=new Map();for(const e of r.entries){if(e.debit==='預金'){const key=e.credit;incoming.set(key,(incoming.get(key)||0)+e.amount);}if(e.credit==='預金'){const key=e.debit;outgoing.set(key,(outgoing.get(key)||0)+e.amount);}}const line=(name,value,delta=false)=>`<div class="flowline"><span>${name}</span><b class="${value<0?'negative':delta?'positive':''}">${delta?signedYen(value):yen(value)}</b></div>`;el('cashFlows').innerHTML=line('月初の預金',r.opening)+[...incoming].map(([k,n])=>line('入金 · '+k,n,true)).join('')+[...outgoing].map(([k,n])=>line('出金 · '+k,-n,true)).join('')+line('月末の預金',r.after.預金);el('cashExplanation').textContent='全部門の入出金を仕訳から集計。売掛金の回収・預り敷金・借入入金は、そのまま当月の利益にはなりません。';};

// v43: all management commands use the replayable, atomic engine operations.
const diversificationBeforeManagement=showDiversification;
showDiversification=function(){diversificationBeforeManagement();const f=state.expansion.fishery,disabled=state.closed||state.ended?'disabled':'';el('shopDialogBody').insertAdjacentHTML('beforeend',`<hr><h3>配置・船の用途・撤退</h3><p>船と店の配置は毎月、出船前に決めます。行動は使わず、能力も下がりません。給与は本人の職種のまま（船員を店に回しても28万円）で、社員・店長が船に乗った月は乗船手当３万円（社保別）が付きます。バイトは船に乗れません。店の従業員が全員船に出た月は、クエの行動は店番に固定されます（採用も行動なので、その月は誰か１人を店に回してから採用します）。</p>${state.expansion.fishery&&Expansion.storeUnmanned(state)?'<p class="audit-notice"><b>店番がいないので、今月はクエが店番です（店番以外の行動はできません）。</b></p>':''}<p>休業は維持費半額、給与と償却は継続。７か月以上連続の休業は税務確認の候補になります。</p>${f?`<p>現在の船用途：${f.use==='charter'?'釣船':'漁業'}</p><button data-boat-use="fishery" ${disabled}>４月の方針：漁業</button><button data-boat-use="charter" ${disabled}>４月の方針：釣船</button><p>釣船は船長１人＋船員１人で出せます（船員２人だと人件費が重くなります）。乗船料は税抜9,000円、定員８人。３・４月は漁より少し儲かり、５月は赤字、６月はトントン、７〜９月は少し黒字、10・11月は漁の半分ほど、12〜２月は赤字になりやすい目安です。乗船客は店舗の来店数にも加算。用途切替は４月に１回です。</p>${f.last?.passengers!==undefined?`<p>直近の乗船客：${f.last.passengers}人</p>`:''}${state.staff.map(p=>`<p>${E.STAFF_CHARACTERS[p.characterId]?.name||p.characterId||p.id} <button data-staff-transfer="${p.id}" data-to="boat" ${disabled||p.role==='parttime'?'disabled':''}>${p.role==='parttime'?'バイトは乗船不可':'船に乗せる'}</button>${wageButtons(p,disabled)}</p>`).join('')}${f.crew.map(p=>`<p>${p.characterId==='madai'?'マダイ':p.id} <button data-staff-transfer="${p.id}" data-to="store" ${disabled}>店に回す</button>${p.homeRole==='parttime'&&state.staffEvents?.some(e=>e.staffId===p.id&&e.type==='offer'&&['pending','deferred'].includes(e.status))?`<button data-boat-promote="${p.id}" ${disabled}>正社員登用（月25万円・社保15％）</button>`:''}${p.role==='crew'&&(p.boatMonths||0)>=24?`<button data-captain-promote="${p.id}" ${disabled}>船長登用（資格取得）</button>`:''}${wageButtons(p,disabled)}</p>`).join('')}<button data-exit-preview="fishery-boat" ${disabled}>船の撤退・精算を試算</button>`:''}${state.expansion.properties.map(p=>`<button data-exit-preview="${p.id}" ${disabled}>${p.name}の売却・精算を試算</button>`).join('')}`);};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.boatPromote){expansionCommit(E.promoteStaff(state,b.dataset.boatPromote));showDiversification();}
 else if(b.dataset.captainPromote){expansionCommit(Expansion.promoteCaptain(state,b.dataset.captainPromote));showDiversification();}
 else if(b.dataset.boatUse){expansionCommit(Expansion.setBoatUse(state,b.dataset.boatUse));showDiversification();}
 else if(b.dataset.staffTransfer){if(b.dataset.to==='boat'&&state.staff.length===1&&typeof confirm==='function'&&!confirm('店番がいないのでクエは店番ですがいいですか？\n（今月は店番以外の行動ができなくなります）'))return;expansionCommit(Expansion.transferStaff(state,b.dataset.staffTransfer,b.dataset.to));showDiversification();}

 else if(b.dataset.exitPreview){const q=Expansion.exitQuote(state,b.dataset.exitPreview);openShop('撤退の確認',`<p>１行動を使います。同じ月は見積もりが変わりません。</p><dl><dt>税抜売却額</dt><dd>${yen(q.price)}</dd><dt>売却消費税（後日納付）</dt><dd>${yen(q.output)}</dd><dt>帳簿価額</dt><dd>${yen(q.book)}</dd><dt>売却損益（特別損益）</dt><dd>${signedYen(q.gain)}</dd><dt>借入一括返済</dt><dd>${yen(q.debt)}</dd><dt>仲介費用・敷金返還</dt><dd>${yen(q.feeCash+q.deposit)}</dd><dt>預金の増減</dt><dd>${signedYen(q.net)}</dd></dl><p>借入を完済できなければ売却しません。船長・船員は元の給与のまま店舗の空き枠へ異動し、空きがない人は当月給与を払って翌月退職します。会社の都合で解雇はできません。人件費を減らしたいときは減給しますが、減給した人は毎月２割の確率で退職届を出します。船への再参入は翌期からです。</p><button data-exit-confirm="${q.id}">この条件で撤退する</button>`);}
 else if(b.dataset.exitConfirm){expansionCommit(Expansion.exitBusiness(state,b.dataset.exitConfirm));showDiversification();}
 }catch(error){toast(error.message);}});
const staffBodyBeforeBoat=staffManagementBody;
staffManagementBody=function(){return staffBodyBeforeBoat()+(state.expansion?.fishery?.crew.some(p=>p.homeRole==='parttime')?'<p>船勤務のバイトも登用・４年退職の対象です。</p><button id="diversificationMenu">船勤務者の登用相談を確認</button>':'');};
